import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.LX5S0jbT.js";const g=JSON.parse('{"title":"配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/configuration.md","filePath":"zh/configuration.md"}'),r={name:"zh/configuration.md"};function c(i,t,n,s,h,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h1><p>Pi 支持用户级和项目级配置。用户级配置位于 agent 目录，默认为 <code>~/.pi/agent</code>。项目配置位于工作目录下的 <code>.pi</code>，在授予<a href="./security.html#understand-project-trust">项目信任</a>后加载。唯一的例外是 <code>sessionDir</code>，Pi 会在解析信任之前读取它以定位会话（session）。</p><p>交互模式下，使用 <code>/settings</code> 更改常用偏好。其他选项可让 Pi 更新配置，或直接编辑相应文件。手动更改设置、键绑定、指令或资源后，运行 <code>/reload</code>。</p><p><a id="agent-directory"></a></p><h2 id="agent-目录" tabindex="-1">Agent 目录 <a class="header-anchor" href="#agent-目录" aria-label="Permalink to &quot;Agent 目录&quot;">​</a></h2><p>下文中 agent 目录表示为 <code>&lt;agent-dir&gt;</code>。通过 <code>PI_CODING_AGENT_DIR</code> 环境变量或 SDK 的 <a href="./sdk.html"><code>agentDir</code></a> 选项设置其位置。</p><table tabindex="0"><thead><tr><th>路径</th><th>职责</th></tr></thead><tbody><tr><td><code>&lt;agent-dir&gt;/settings.json</code></td><td>用户级<a href="./settings.html">设置</a>，包括偏好、默认值、资源路径和 Pi 包声明。</td></tr><tr><td><code>&lt;agent-dir&gt;/keybindings.json</code></td><td>自定义终端 UI 和应用<a href="./keybindings.html">键绑定</a>。</td></tr><tr><td><code>&lt;agent-dir&gt;/mcp.json</code></td><td>每个项目都可用的 <a href="./mcp.html">MCP 服务器</a>。</td></tr><tr><td><code>&lt;agent-dir&gt;/models.json</code></td><td><a href="./models.html#configure-a-compatible-endpoint">兼容端点、模型和模型覆盖</a>。</td></tr><tr><td><code>&lt;agent-dir&gt;/auth.json</code></td><td>已保存的 API key 和 OAuth 凭据。</td></tr><tr><td><code>&lt;agent-dir&gt;/AGENTS.override.md</code>、<code>AGENTS.md</code>、<code>AGENTS.MD</code>、<code>CLAUDE.md</code> 或 <code>CLAUDE.MD</code></td><td>跨工作目录应用的用户指令。</td></tr><tr><td><code>&lt;agent-dir&gt;/SYSTEM.md</code></td><td>替换 Pi 的默认系统提示词。</td></tr><tr><td><code>&lt;agent-dir&gt;/APPEND_SYSTEM.md</code></td><td>向 Pi 的系统提示词添加指令。</td></tr><tr><td><code>&lt;agent-dir&gt;/extensions/</code></td><td>用户<a href="./extensions.html">扩展</a>。</td></tr><tr><td><code>&lt;agent-dir&gt;/skills/</code></td><td>用户<a href="./skills.html">技能</a>及配套文件。</td></tr><tr><td><code>&lt;agent-dir&gt;/prompts/</code></td><td>作为斜杠命令暴露的用户<a href="./prompt-templates.html">提示词模板</a>。</td></tr><tr><td><code>&lt;agent-dir&gt;/themes/</code></td><td>用户<a href="./themes.html">主题</a>文件。</td></tr></tbody></table><h2 id="项目-pi-目录" tabindex="-1">项目 <code>.pi</code> 目录 <a class="header-anchor" href="#项目-pi-目录" aria-label="Permalink to &quot;项目 `.pi` 目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>职责</th></tr></thead><tbody><tr><td><code>.pi/settings.json</code></td><td>项目级<a href="./settings.html">设置</a>、资源路径和 Pi 包声明。</td></tr><tr><td><code>.pi/mcp.json</code></td><td>项目 <a href="./mcp.html">MCP 服务器</a>。</td></tr><tr><td><code>.pi/SYSTEM.md</code></td><td>替换项目的系统提示词。</td></tr><tr><td><code>.pi/APPEND_SYSTEM.md</code></td><td>向系统提示词添加项目专属指令。</td></tr><tr><td><code>.pi/extensions/</code></td><td>项目扩展。</td></tr><tr><td><code>.pi/skills/</code></td><td>项目技能及配套文件。</td></tr><tr><td><code>.pi/prompts/</code></td><td>作为斜杠命令暴露的项目提示词模板。</td></tr><tr><td><code>.pi/themes/</code></td><td>项目主题文件。</td></tr></tbody></table><p>对于 <code>SYSTEM.md</code> 和 <code>APPEND_SYSTEM.md</code>，受信任的项目文件优先于 agent 目录中的对应文件。同名文件不会合并。</p><p><a id="context-files"></a></p><h2 id="上下文文件" tabindex="-1">上下文文件 <a class="header-anchor" href="#上下文文件" aria-label="Permalink to &quot;上下文文件&quot;">​</a></h2><p>上下文文件独立于项目 <code>.pi</code> 配置。Pi 从 agent 目录、工作目录及其父目录加载它们。只要 Pi 在某个上下文文件所在目录或其下层目录中运行，该文件就会生效。</p><p><code>AGENTS.override.md</code> 只在同一目录中替换 <code>AGENTS.md</code> 或 <code>CLAUDE.md</code>。它不会屏蔽来自 agent 目录或其他目录的上下文文件。</p><p>上下文文件的发现不需要项目信任。</p>',15)])])}const m=d(r,[["render",c]]);export{g as __pageData,m as default};
